"""College-Level and Simplified wordings for Module I quiz questions. Collections 03 and 04."""
V = {}
def v(qid, college, simple):
    V[qid] = (college, simple)

# Collection 03 · Perception · Part 2
v(39, ('In Palmer (1975), after which kind of scene were objects identified most accurately?', 'A scene that was appropriate for the object.', 'A scene that was inappropriate for the object.', 'A scene that was shown after the object.', 'No scene at all.'),
      ('In Palmer (1975), did the scene affect how well an object was identified?', 'Yes. Objects were identified best after a scene they fit.', 'No. The scene made no difference.', 'Yes. Objects were identified best after a scene they did not fit.', 'Yes, but only for faces.'))
v(40, ('The Müller-Lyer illusion is weaker in some populations than in others. What does this caution against?', 'Assuming that one population stands for perception in all people.', 'Using controlled experiments to study vision.', 'Treating experience as a source of priors.', 'Measuring the physical length of the lines.'),
      ('Is the Müller-Lyer illusion equally strong in all populations?', 'No. Its strength differs across populations.', 'Yes. It is the same everywhere.', 'It appears only in children.', 'It appears only in adults.'))
v(41, ('What does WEIRD stand for?', 'Western, Educated, Industrialized, Rich, Democratic.', 'Western, Experienced, Intelligent, Rich, Diverse.', 'Wealthy, Educated, Independent, Rural, Democratic.', 'Western, Educated, Introspective, Rational, Developed.'),
      ('What kind of countries does WEIRD describe?', 'Western, Educated, Industrialized, Rich and Democratic countries.', 'Countries with no psychology research.', 'Countries that were never industrialized.', 'Countries where the Müller-Lyer illusion is absent.'))
v(42, ('In Blakemore and Cooper (1970), kittens reared with only vertical stripes had neurons that responded mainly to verticals. What does this support?', 'Experience-dependent plasticity.', 'Tuning that is fixed at birth.', 'The light-from-above assumption.', 'Recognition by components.'),
      ('What is experience-dependent plasticity?', 'The brain’s structure is changed by experience.', 'The brain’s structure cannot change.', 'Neurons respond equally to everything.', 'Perception does not depend on the brain.'))
v(43, ('In Gauthier and colleagues (1999), the FFA responded more to Greebles after training. What is this evidence for?', 'Expertise changes how the area responds.', 'The FFA responds only to faces.', 'New object categories cannot be learned.', 'The Greeble images were changed.'),
      ('What happened to the FFA response to Greebles after training?', 'It increased.', 'It decreased.', 'It stayed the same.', 'It disappeared.'))
v(44, ('Changes in saturation slow down a judgment of brightness. What kind of dimensions are brightness and saturation?', 'Integral dimensions.', 'Separable dimensions.', 'Semantic dimensions.', 'Physical regularities.'),
      ('What is Garner interference?', 'Slower responses when an irrelevant dimension varies.', 'Faster responses when an irrelevant dimension varies.', 'Missing a change between two images.', 'Seeing movement that is not there.'))
v(168, ('What did Gestalt psychologists claim about the laws of perceptual organization?', 'The laws are built into the visual system and are not learned.', 'The laws are learned through language.', 'The laws must be applied consciously.', 'The laws apply only to movement.'),
       ('According to the Gestalt psychologists, are the laws of organization learned?', 'No. They are built in.', 'Yes. They are learned from experience with scenes.', 'Yes. They are learned from language.', 'They are learned only by adults.'))
v(169, ('Which pair gives a physical regularity and then a semantic regularity?', 'Light usually comes from above. Kitchens usually contain stoves.', 'Kitchens usually contain stoves. Light usually comes from above.', 'Streets contain cars. Offices contain chairs.', 'Verticals are common. Surfaces are mostly one color.'),
       ('Is “light comes from above” a physical or a semantic regularity?', 'A physical regularity.', 'A semantic regularity.', 'Both.', 'Neither.'))
v(170, ('What is ontogeny?', 'The development of an individual.', 'The evolutionary history of a species.', 'The time needed to select a response.', 'The meaning of a scene.'),
       ('What is phylogeny?', 'Evolutionary history.', 'The development of one individual.', 'A kind of illusion.', 'A brain area.'))
v(171, ('A vertical line is detected more accurately than a slanted line that is just as visible. What is this called?', 'The oblique effect.', 'The Müller-Lyer illusion.', 'Garner interference.', 'Experience-dependent plasticity.'),
       ('Which lines are perceived more easily, verticals or obliques?', 'Verticals.', 'Obliques.', 'Both equally.', 'Neither.'))
v(172, ('What can turn a bump into a dent without changing the object that was photographed?', 'Rotating the image, which changes how the shading fits light from above.', 'Placing a new object behind the camera.', 'Showing the image for a longer time.', 'Removing all shading from the image.'),
       ('What information do shadows give?', 'Information about depth and distance.', 'Information about color only.', 'Information about the object’s name.', 'Information about the object’s weight only.'))
v(173, ('You expect to see a projector in a classroom. What kind of knowledge is this?', 'A scene schema.', 'A physical regularity.', 'A prior about lighting.', 'A Gestalt law.'),
       ('What is a scene schema?', 'Knowledge of what a given scene ordinarily contains.', 'A map of the visual cortex.', 'A measure of illusion strength.', 'A rule about lighting.'))
v(174, ('In Palmer (1975), what was measured?', 'How accurately the object was identified.', 'How long the scene was remembered.', 'How large the object appeared.', 'How quickly the eyes moved.'),
       ('In Palmer (1975), what was shown before the object?', 'A scene.', 'A word.', 'A sound.', 'A face.'))
v(175, ('Two different objects could have produced the same retinal image. How does the inferential approach decide between them?', 'It uses knowledge of regularities in the environment together with the image.', 'It uses the image alone, which identifies one object.', 'It treats both objects as equally probable.', 'It waits for the observer to move.'),
       ('What does the inferential approach select?', 'The most probable interpretation of the image.', 'The simplest shape.', 'The first interpretation that comes up.', 'Every interpretation at once.'))
v(176, ('A rare cause and a common cause both explain a symptom well. What does Bayesian inference need in order to choose between them?', 'Both the priors and the likelihoods.', 'The likelihoods only.', 'The priors only.', 'Neither priors nor likelihoods.'),
       ('Why is Mary’s cough most likely a cold?', 'Colds are common and colds reliably cause coughing.', 'Colds are rare.', 'Colds never cause coughing.', 'Heartburn causes most coughs.'))
v(177, ('In P(H|E) = P(E|H)P(H) / P(E), the likelihood P(E|H) is easy to confuse with another term. Which term is the probability that the hypothesis is correct, given the image?', 'P(H|E), the posterior.', 'P(E|H), the likelihood.', 'P(H), the prior.', 'P(E), the probability of the image.'),
       ('In Bayesian inference, what is H?', 'A perceptual hypothesis.', 'The image received.', 'The response time.', 'The retina.'))
v(178, ('Which of the four approaches to object perception relies least on learned knowledge?', 'The Gestalt laws of organization.', 'Helmholtz’s unconscious inference.', 'Regularities in the environment.', 'Bayesian inference.'),
       ('Which approach says the principles of organization are built in?', 'The Gestalt approach.', 'Bayesian inference.', 'Helmholtz’s unconscious inference.', 'Regularities in the environment.'))
v(179, ('The same two lines are judged differently in different cultures. What is the most careful conclusion?', 'Perceptual biases can differ across populations.', 'One population cannot see the lines.', 'Every visual mechanism differs between the populations.', 'The lines changed between the tests.'),
       ('In Segall and colleagues (1966), which group was unaffected by the Müller-Lyer illusion?', 'San foragers in the Kalahari.', 'American undergraduates.', 'Participants from WEIRD countries.', 'Greeble experts.'))
v(180, ('What does Henrich (2008) connect the Müller-Lyer illusion with?', 'Experience with the carpentered corners of built environments.', 'The number of words for length in a language.', 'Experience with vertical stripes early in life.', 'Training to recognize a new class of objects.'),
       ('What are carpentered corners?', 'The right-angled corners of built environments.', 'Corners of the visual field.', 'Parts of the retina.', 'The corners of the Müller-Lyer fins.'))
v(181, ('Why is a result from a WEIRD sample not enough to show that a finding is universal?', 'The sample may not represent the range of human environments and experience.', 'Results from such samples cannot be replicated.', 'People in such samples do not see illusions.', 'Laboratory tasks are always invalid.'),
       ('Who challenged generalizing from WEIRD samples?', 'Henrich, Heine and Norenzayan (2010).', 'Blakemore and Cooper (1970).', 'Palmer (1975).', 'Fodor (1983).'))
v(182, ('Which result would show that learning shapes neural tuning?', 'Neurons change what they respond to after a change in experience.', 'Neurons respond the same way after every kind of experience.', 'Neurons respond only to faces.', 'Neurons stop responding to verticals in all animals.'),
       ('Which orientations do many neurons respond to best?', 'Horizontals and verticals.', 'Obliques.', 'All orientations equally.', 'None.'))
v(183, ('How do the FFA and the PPA differ?', 'The FFA responds strongly to faces, and the PPA responds strongly to places.', 'The FFA responds to places, and the PPA responds to faces.', 'Both respond only to Greebles.', 'Neither has a preferred category.'),
       ('What does the PPA respond to strongly?', 'Places and scenes.', 'Faces.', 'Words.', 'Sounds.'))
v(184, ('Why did Gauthier and colleagues (1999) compare responses to Greebles before and after training?', 'To test whether expertise changes the response to the same objects.', 'To show that object recognition is fixed at birth.', 'To measure the participants’ memory for faces.', 'To change the appearance of the Greebles.'),
       ('How long was the Greeble training?', 'Four days.', 'Four hours.', 'Four weeks.', 'Four months.'))
v(185, ('Why can walking around an unfamiliar object improve recognition?', 'New viewpoints give information that one still view does not.', 'The object becomes a different object.', 'Memory is no longer needed.', 'The eyes stop moving.'),
       ('Does movement help perception?', 'Yes. Movement helps us perceive things more accurately.', 'No. Movement always makes perception worse.', 'Only the object’s movement helps.', 'Only when the observer stands still.'))
v(186, ('What link does the sticky mittens study test?', 'The link between manual exploration and visual development.', 'The link between scene context and object identification.', 'The link between Greeble training and the FFA.', 'The link between stripe rearing and neural tuning.'),
       ('What do sticky mittens let infants do?', 'Contact and act on objects before they can grasp well.', 'See colors more clearly.', 'Hear speech more clearly.', 'Walk earlier.'))

# Collection 04 · Attention · Part 1
v(45, ('A person follows one conversation and ignores another. Which kind of attention is this?', 'Selective attention.', 'Divided attention.', 'Attentional capture.', 'Covert attention.'),
      ('What is selective attention?', 'Attending to one thing while ignoring others.', 'Attending to more than one thing at a time.', 'A sudden shift of attention caused by a loud noise.', 'Moving the eyes from place to place.'))
v(46, ('In the dichotic listening task of Cherry (1953), why are participants asked to shadow a message?', 'It ensures that attention is on that message.', 'It measures the meaning of the other message.', 'It stops sound reaching the other ear.', 'It removes the need for any response.'),
      ('In dichotic listening, how many messages are presented?', 'Two, one to each ear.', 'One, to both ears.', 'One, to one ear.', 'Three.'))
v(47, ('Listeners noticed the gender of the voice in the unattended ear and could not report its content. What does this show?', 'Physical features were processed, and the meaning was not available for report.', 'Nothing in the unattended ear was processed.', 'The whole unattended message was understood.', 'No sound reached the unattended ear.'),
      ('What could listeners report about the unattended message?', 'That there was a message, and the gender of the speaker.', 'Every word of the message.', 'The topic of the message.', 'Nothing at all.'))
v(48, ('In the filter model of Broadbent (1958), what does the filter use to select the attended message?', 'Physical characteristics, before meaning is analyzed.', 'The meaning of each message.', 'The importance of each word.', 'The frequency of each word.'),
      ('Is Broadbent’s model early selection or late selection?', 'Early selection.', 'Late selection.', 'Intermediate selection.', 'No selection.'))
v(49, ('In Moray (1959), about one third of listeners detected their own name in the unattended ear. Which idea does this go against?', 'A filter that blocks all unattended meaning.', 'A filter that weakens the unattended message.', 'Selection after meaning is analyzed.', 'Low thresholds for important words.'),
      ('In Moray (1959), what did some listeners detect in the unattended ear?', 'Their own name.', 'A change of language.', 'A list of numbers.', 'Nothing.'))
v(50, ('In the attenuation theory of Treisman (1964), what happens to the unattended message?', 'It is weakened and not shut off.', 'It is blocked completely.', 'It is passed at full strength.', 'It is processed before the attended message.'),
      ('What does “attenuated” mean in Treisman’s theory?', 'Weakened.', 'Blocked.', 'Strengthened.', 'Repeated.'))
v(51, ('In Treisman’s theory, why can a person’s own name be detected in the unattended message?', 'The name has a low threshold in the dictionary unit.', 'The name has a high threshold in the dictionary unit.', 'The name is not stored in the dictionary unit.', 'The name is louder than other words.'),
      ('Which words have low thresholds in the dictionary unit?', 'Common or important words.', 'Uncommon words.', 'Long words.', 'New words.'))
v(52, ('In MacKay (1973), an unattended word changed how “bank” was understood. What does this support?', 'The unattended word was processed for meaning.', 'Only the pitch of the unattended word was processed.', 'The unattended word had no influence.', 'The attended sentence was changed.'),
      ('In MacKay (1973), were participants aware of the biasing word?', 'No. They were unaware of it.', 'Yes. They reported it every time.', 'Yes, but only “river.”', 'Yes, but only “money.”'))
v(53, ('How was the debate between early and late selection resolved?', 'Early selection occurs under some conditions and late selection under others.', 'Early selection was shown to be correct in every task.', 'Late selection was shown to be correct in every task.', 'Selection was shown not to occur.'),
      ('Is there a single answer to the early versus late selection debate?', 'No. It depends on the conditions.', 'Yes. Selection is always early.', 'Yes. Selection is always late.', 'Yes. Selection is always in the middle.'))
v(54, ('According to load theory, when does an irrelevant stimulus interfere most?', 'When the main task has a low perceptual load.', 'When the main task uses all the available capacity.', 'When no irrelevant stimulus is present.', 'When the main task is very difficult.'),
      ('What is perceptual load?', 'The difficulty of a task.', 'The loudness of a sound.', 'The number of participants.', 'The length of an experiment.'))
v(55, ('Why are eye movements monitored in experiments on covert attention?', 'To confirm that the eyes stayed fixed.', 'To measure covert attention directly.', 'To measure the sensitivity of the retina.', 'To show that every object was seen.'),
      ('What is covert attention?', 'Shifting attention while the eyes stay fixed.', 'Shifting attention by moving the eyes.', 'Attending to two tasks at once.', 'Ignoring a message.'))
v(56, ('What is a rapid movement of the eyes from one place to another called?', 'A saccade.', 'A fixation.', 'A precue.', 'An attentional capture.'),
      ('What is a fixation?', 'A short pause of the eyes on a point of interest.', 'A rapid eye movement.', 'A blink.', 'A shift of covert attention.'))
v(57, ('A sudden bright flash draws attention. What is this mainly due to?', 'Stimulus salience, which is bottom-up.', 'A scene schema, which is top-down.', 'The demands of the task.', 'A valid cue.'),
      ('Is stimulus salience bottom-up or top-down?', 'Bottom-up.', 'Top-down.', 'Both equally.', 'Neither.'))
v(58, ('A person looks for a door handle at the edge of a door and not on the ceiling. What guides this?', 'A scene schema.', 'Stimulus salience.', 'Attentional capture.', 'An invalid cue.'),
      ('Are scene schemas a bottom-up or a top-down influence on eye movements?', 'Top-down.', 'Bottom-up.', 'Neither.', 'They do not affect eye movements.'))
v(59, ('Which of these is top-down guidance of attention while driving?', 'Looking at a license plate from a distant state because it interests you.', 'Looking toward a reflection that hits your eyes.', 'Looking at a ball that suddenly rolls into the road.', 'Looking at a bright pink object because of its color.'),
       ('Does the task a person is doing affect where they look?', 'Yes. Gaze goes to the objects needed for the task.', 'No. Gaze goes only to bright objects.', 'No. Gaze is random.', 'Only when the person is driving.'))
v(60, ('In Posner and colleagues (1978), responses were faster after a valid cue while the eyes stayed fixed. What does this support?', 'Covert attention to a location.', 'Overt attention only.', 'No effect of attention.', 'Object-based attention only.'),
      ('What is a valid cue?', 'A cue that indicates where the target will appear.', 'A cue that points away from the target.', 'A cue that appears after the target.', 'A cue with no target.'))
v(61, ('In Egly and colleagues (1994), a target was detected faster on the cued object than on another object the same distance away. What does this support?', 'Object-based attention.', 'Attention based on distance alone.', 'Early selection.', 'Automatic processing.'),
      ('What is the same-object advantage?', 'Attention to one place on an object spreads to other places on that object.', 'Attention never spreads within an object.', 'Objects are seen better on the left.', 'Larger objects are detected faster.'))
v(62, ('In Schneider and Shiffrin (1977), after about how many trials had the task become automatic?', 'About 600 trials.', 'About 6 trials.', 'About 60 trials.', 'About 6,000 trials.'),
      ('What did practice do in the task of Schneider and Shiffrin (1977)?', 'It made the task automatic.', 'It made the task slower.', 'It had no effect.', 'It made the task impossible.'))
v(154, ('Which statements are true? I. Covert attention requires a saccade. II. Fixations are pauses. III. The fovea has higher resolution than the periphery.', 'II and III only.', 'I and II only.', 'I, II and III.', 'I only.'),
       ('Which part of the eye has the highest resolution?', 'The fovea.', 'The periphery.', 'The optic nerve.', 'The lens.'))
v(187, ('Why is the filter model of Broadbent (1958) called a bottleneck model?', 'The filter restricts which information goes on.', 'Every message is slowed and then fully analyzed.', 'Unattended meaning always reaches awareness.', 'Processing capacity has no limit.'),
       ('In Broadbent’s model, how many messages pass the filter?', 'Only the attended message.', 'Both messages.', 'Neither message.', 'All messages, weakened.'))
v(188, ('In Gray and Wedderburn (1960), participants reported “Dear Aunt Jane” although the words arrived at different ears. Which kind of selection does this go against?', 'Selection based only on physical characteristics such as the ear.', 'Selection that follows the meaning of a message.', 'Selection after meaning is analyzed.', 'Selection by word thresholds.'),
       ('Who ran the “Dear Aunt Jane” experiment?', 'Gray and Wedderburn (1960).', 'Cherry (1953).', 'Broadbent (1958).', 'MacKay (1973).'))
v(189, ('In Treisman’s theory, which word is most likely to be activated by a weakened message?', 'A person’s own name.', 'An uncommon word with a high threshold.', 'Any rare word.', 'No word at all.'),
       ('What does each word in the dictionary unit have?', 'A threshold for being activated.', 'A fixed strength in the attenuator.', 'A physical location in the ear.', 'A filter of its own.'))
v(190, ('In MacKay (1973), listeners did not report the biasing word and it still changed their choice. What two things does this separate?', 'Being influenced by a word’s meaning and being aware of the word.', 'Being attenuated by the filter and being blocked by the filter.', 'Shadowing a message aloud and hearing the same message.', 'Filtering a message early and using its physical features.'),
       ('Which model does MacKay (1973) support?', 'Late selection.', 'Early selection.', 'The filter model.', 'No model.'))
v(191, ('In Forster and Lavie (2008), a distractor slowed an easy task more than a hard task. Which theory predicts this?', 'Load theory.', 'The filter model.', 'Attenuation theory.', 'Feature integration theory.'),
       ('In Forster and Lavie (2008), when was distraction stronger?', 'In easier tasks.', 'In harder tasks.', 'It was the same in both.', 'There was no distraction.'))
v(192, ('A participant keeps looking at a central cross and responds faster to a target at a cued location. What kind of shift of attention is this?', 'A covert shift.', 'An overt shift.', 'A saccade.', 'A fixation on the target.'),
       ('What is overt attention?', 'Shifting attention by moving the eyes.', 'Shifting attention with the eyes fixed.', 'Attending to sounds.', 'Attending to two things at once.'))
